HELPER_SQL = r'''
-- These helpers run with the caller's rights. They do not authenticate a user or bypass RLS.
CREATE FUNCTION public.sa_has_role(p_user uuid, p_role text, p_department uuid DEFAULT NULL,
 p_at timestamptz DEFAULT now()) RETURNS boolean
LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,public AS $fn$
 SELECT EXISTS (
 SELECT 1 FROM public.users u JOIN public.user_roles g ON g.user_id=u.user_id
 JOIN public.roles r ON r.role_id=g.role_id AND r.scope_type=g.scope_type
 WHERE u.user_id=p_user AND u.status='active' AND r.status='active'
 AND r.allowed_account_type=u.account_type AND r.role_code=p_role
 AND g.granted_at<=p_at AND (g.revoked_at IS NULL OR g.revoked_at>p_at)
 AND (g.scope_type='global' OR g.department_id=p_department));
$fn$;

CREATE FUNCTION public.sa_po_progress(p_po uuid, p_asof timestamptz DEFAULT now())
RETURNS TABLE(po_item_id uuid, ordered_qty numeric, received_qty numeric, remaining_qty numeric,
 original_deadline date, last_receipt_known_at timestamptz)
LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,public AS $fn$
 SELECT i.po_item_id, i.ordered_quantity, coalesce(r.qty,0),
 greatest(i.ordered_quantity-coalesce(r.qty,0),0), s.deadline, r.known_at
 FROM public.purchase_order_items i
 JOIN public.purchase_orders o ON o.purchase_order_id=i.purchase_order_id
 LEFT JOIN LATERAL (SELECT max(sc.requested_delivery_date) deadline
 FROM public.purchase_order_schedules sc WHERE sc.po_item_id=i.po_item_id) s ON true
 LEFT JOIN LATERAL (SELECT sum(g.received_quantity) qty, max(g.received_at) known_at
 FROM public.goods_receipts g JOIN public.purchase_order_schedules sc ON sc.schedule_id=g.schedule_id
 WHERE sc.po_item_id=i.po_item_id AND g.received_at<=p_asof
 AND g.actual_delivery_date<=(p_asof AT TIME ZONE 'Asia/Ho_Chi_Minh')::date) r ON true
 WHERE i.purchase_order_id=p_po AND o.order_date<=p_asof;
$fn$;

-- Only the supplier actually ordered gets an observed label. Open orders are excluded.
-- For this demo every item has exactly one frozen schedule/deadline.
CREATE FUNCTION public.sa_training_rows(p_cutoff timestamptz DEFAULT now())
RETURNS TABLE(prediction_id uuid, group_id uuid, feature_asof timestamptz,
 prediction_stage varchar, x jsonb, label integer, label_available_at timestamptz)
LANGUAGE sql STABLE SECURITY INVOKER SET search_path=pg_catalog,public AS $fn$
 SELECT p.prediction_id, i.po_item_id, p.feature_asof, p.prediction_stage,
 p.feature_snapshot->'x', (r.actual_date>p.requested_delivery_date)::integer, r.known_at
 FROM public.risk_predictions p
 JOIN public.purchase_order_items i ON i.request_item_id=p.request_item_id
 JOIN public.purchase_orders o ON o.purchase_order_id=i.purchase_order_id AND o.supplier_id=p.supplier_id
 JOIN LATERAL (SELECT sum(g.received_quantity) qty, max(g.actual_delivery_date) actual_date,
 max(g.received_at) known_at FROM public.goods_receipts g
 JOIN public.purchase_order_schedules s ON s.schedule_id=g.schedule_id
 WHERE s.po_item_id=i.po_item_id AND g.received_at<=p_cutoff) r ON r.qty>=i.ordered_quantity
 WHERE p.feature_asof<=p_cutoff AND p.feature_asof<r.known_at
 AND (p.po_item_id IS NULL OR p.po_item_id=i.po_item_id);
$fn$;
REVOKE ALL ON FUNCTION public.sa_has_role(uuid,text,uuid,timestamptz) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.sa_po_progress(uuid,timestamptz) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.sa_training_rows(timestamptz) FROM PUBLIC,anon,authenticated;
'''

def stamp(value):
    if isinstance(value,(date,datetime)): return value.isoformat()
    if isinstance(value,(Decimal,UUID)): return str(value)
    return value

def literal(value):
    if value is None: return 'NULL'
    if isinstance(value,bool): return 'TRUE' if value else 'FALSE'
    if isinstance(value,(int,float,Decimal)):
        if not math.isfinite(float(value)): raise ValueError('Nonfinite SQL numeric')
        return str(value)
    if isinstance(value,(dict,list)): value=json.dumps(value,default=stamp,ensure_ascii=False,allow_nan=False)
    elif isinstance(value,(date,datetime,UUID)): value=str(value)
    if '\x00' in value: raise ValueError('NUL is not permitted')
    return "'"+value.replace("'","''")+"'"

def quantile(values, p):
    if not values: return None
    values=sorted(values); pos=(len(values)-1)*p; low=int(pos)
    return round(values[low]+(values[min(low+1,len(values)-1)]-values[low])*(pos-low),4)

def workday_after(start, n):
    current=start.date()
    for _ in range(int(n)):
        current+=timedelta(days=1)
        while current.weekday()>=5: current+=timedelta(days=1)
    return datetime.combine(current,time(10),TZ)

def nonworking(start, deadline):
    if deadline<=start.date(): return 0
    return sum((start.date()+timedelta(days=i)).weekday()>=5
               for i in range(1,(deadline-start.date()).days+1))

class Demo:
    def __init__(self, count, seed, asof):
        self.rng=random.Random(seed); self.seed=seed; self.asof=asof
        self.epoch=asof-timedelta(days=650)
        self.rows={t:[] for t in TABLES}; self.counter={t:0 for t in TABLES}
        self.orders=[]; self.samples=[]; self.pairs=[]; self.count=count
        self.namespace=uuid5(NAMESPACE_URL,f'flowbridge-synthetic-v1/{seed}/{asof.isoformat()}')
    def uid(self,key): return uuid5(self.namespace,key)
    def add(self,table,**kw):
        self.counter[table]+=1; key=COLUMNS[table][0]
        kw.setdefault(key,self.uid(f'{table}/{self.counter[table]}'))
        if 'created_at' in COLUMNS[table]: kw.setdefault('created_at',self.epoch)
        if 'updated_at' in COLUMNS[table]: kw.setdefault('updated_at',kw.get('created_at',self.epoch))
        assert set(kw)<=set(COLUMNS[table]),(table,set(kw)-set(COLUMNS[table]))
        for name in REQUIRED[table]:
            assert kw.get(name) is not None,(table,name)
        self.rows[table].append(kw); return kw[key]
    def masters(self):
        r=self.rng
        self.depts=[self.add('departments',department_code=f'DEMO-D{i}',department_name=f'Demo department {i}',status='active') for i in range(1,5)]
        def user(name,kind='human',dept=None):
            return self.add('users',external_issuer='urn:flowbridge:demo:NOT-A-REAL-IDP',external_subject=name,
                display_name=name,email=f'{name}@example.invalid',department_id=dept,account_type=kind,status='active')
        self.admin=user('demo-admin'); self.ai=user('demo-ai','service'); self.po_service=user('demo-po-service','service')
        self.employee={d:[user(f'demo-staff-{i}-{j}',dept=d) for j in range(3)] for i,d in enumerate(self.depts)}
        self.approver={d:user(f'demo-approver-{i}',dept=d) for i,d in enumerate(self.depts)}
        self.warehouse={d:user(f'demo-warehouse-{i}',dept=d) for i,d in enumerate(self.depts)}
        role_specs=[('EMPLOYEE','human','global'),('APPROVER','human','department'),('WAREHOUSE','human','department'),
                    ('ADMIN','human','global'),('AI_SERVICE','service','global'),('PO_SERVICE','service','global')]
        role_ids={code:self.add('roles',role_code=code,role_name=code,description='Synthetic demo role',
                    allowed_account_type=kind,scope_type=scope,status='active') for code,kind,scope in role_specs}
        def grant(u,code,d=None):
            self.add('user_roles',user_id=u,role_id=role_ids[code],scope_type='department' if d else 'global',
                     department_id=d,granted_by=self.admin,granted_at=self.epoch)
        grant(self.admin,'ADMIN'); grant(self.ai,'AI_SERVICE'); grant(self.po_service,'PO_SERVICE')
        for d in self.depts:
            for u in self.employee[d]: grant(u,'EMPLOYEE')
            grant(self.approver[d],'APPROVER',d); grant(self.warehouse[d],'WAREHOUSE',d)
        self.suppliers=[]
        for i in range(6):
            sid=self.add('suppliers',supplier_code=f'DEMO-S{i+1:02}',supplier_name=f'Demo Supplier {i+1}',
                email=f'supplier-{i+1}@example.invalid',city=['Hanoi','Danang','HCMC'][i%3],country_of_origin='VN',status='active')
            self.suppliers.append(dict(id=sid,median=3+r.gammavariate(4,1.25),sigma=r.uniform(.18,.36),
                                       shock_p=r.betavariate(2,12)))
        self.products=[]; self.offers={}
        for i in range(6):
            typical=[20,40,60,25,50,100][i]; category=['office','electronics','materials'][i%3]
            pid=self.add('products',product_code=f'DEMO-P{i+1:02}',product_name=f'Demo Product {i+1}',
                product_category=category,unit='unit',description=f'DEMO catalog normalization quantity={typical}; simulator config, not estimated from future purchases',status='active')
            p=dict(id=pid,category=category,typical=typical,factor=[.8,1.2,1.5][i%3]); self.products.append(p)
            for s in self.suppliers:
                price=Decimal(str(round((i+1)*25000*(.8+2/s['median'])*r.uniform(.95,1.05),4)))
                quoted=round(s['median']*p['factor'])
                self.offers[s['id'],pid]=dict(price=price,lead=quoted)
                self.add('supplier_products',supplier_id=s['id'],product_id=pid,current_unit_price=price,currency='VND',
                         min_order_qty=1,quoted_lead_days=quoted,is_available=True,updated_at=self.epoch)
            for days in (90,30,0):
                self.add('inventory_snapshots',product_id=pid,location_code='DEMO-WH',on_hand_qty=typical*r.randint(2,8),
                         safety_stock_qty=typical,snapshot_at=self.asof-timedelta(days=days))

    def visible_receipts(self,o,at): return [x for x in o['receipts'] if x['known']<=at]
    def completed(self,o,at):
        rr=self.visible_receipts(o,at)
        return sum(x['qty'] for x in rr)>=o['qty']
    def features(self,s,p,qty,deadline,at,stage,o=None):
        hist=[h for h in self.orders if h['s']['id']==s['id'] and h['p']['id']==p['id']
              and h['created']<at and self.completed(h,at)
              and h['final_known']>=at-timedelta(days=180)]
        leads=[(h['arrival'].date()-h['issue'].date()).days for h in hist]
        n=len(hist); late=sum(h['arrival'].date()>h['deadline'] for h in hist)
        backlog=sum(h['s']['id']==s['id'] and h['issue']<=at and not self.completed(h,at)
                    and h is not o for h in self.orders)
        x=dict.fromkeys(FEATURES)
        x.update(prediction_stage=stage,supplier_id=str(s['id']),product_category=p['category'],
            order_size_ratio=round(qty/p['typical'],5),days_to_deadline=(deadline-at.date()).days,
            non_working_days_to_deadline=nonworking(at,deadline),hist_lead_p50_days=quantile(leads,.5),
            hist_lead_p90_days=quantile(leads,.9),hist_late_rate_smoothed=round((late+2)/(n+4),5) if n else None,
            hist_sample_count=n,other_open_order_count=backlog,
            expected_issue_wait_days=3.0 if stage=='PR_CREATED' else 0.0)
        if o is not None:
            rr=self.visible_receipts(o,at); received=sum(v['qty'] for v in rr)
            confirmations=[c for c in o['confirmations'] if c['known']<=at]
            confirmed=bool(confirmations)
            x.update(remaining_size_ratio=round((qty-received)/p['typical'],5),
              elapsed_days_since_issue=round((at-o['issue']).total_seconds()/86400,5),
              confirmation_state='confirmed' if confirmed else 'pending',
              confirmation_wait_days=round(((confirmations[0]['known'] if confirmed else at)-o['issue']).total_seconds()/86400,5),
              received_fraction=round(received/qty,5),
              days_since_last_receipt=round((at-max(v['known'] for v in rr)).total_seconds()/86400,5) if rr else None,
              promise_margin_days=(confirmations[-1]['promise']-deadline).days if confirmed else None)
        assert set(x)==set(FEATURES) and len(x)==19
        assert all(v is None for k,v in x.items() if stage=='PR_CREATED' and k in TRACKING)
        audit=dict(history_max_known_at=max((h['final_known'] for h in hist),default=None),
                   receipt_max_known_at=max((v['known'] for v in self.visible_receipts(o,at)),default=None) if o else None,
                   confirmation_max_known_at=max((c['known'] for c in o['confirmations'] if c['known']<=at),default=None) if o else None)
        assert all(t is None or t<=at for t in audit.values())
        return x,audit

    def prediction(self,o,s,task,at,stage,x,audit,selected=False):
        pid=self.add('risk_predictions',task_id=task,request_item_id=o['request_item'],request_id=o['request'],input_revision=1,
          source_type='pr_initial' if stage=='PR_CREATED' else 'po_monitoring',prediction_stage=stage,
          po_item_id=o['po_item'] if stage=='PO_MONITORING' else None,
          idempotency_key=f'demo-pred/{stage}/{o["n"]}/{s["id"]}',supplier_id=s['id'],product_id=o['p']['id'],
          quantity=o['qty'],requested_delivery_date=o['deadline'],feature_asof=at,
          requested_lead_days=(o['deadline']-at.date()).days,feature_schema_version='tabicl_supplier_fixed_v1',
          preprocessing_version='not-run:synthetic-raw-v1',model_name=None,model_version=None,
          context_dataset_version=None,context_metadata=None,risk_score=None,risk_threshold=None,risk_level=None,
          feature_snapshot={'x':x,'demo':True,'source_observed_at':at,'synthetic_generator':'causal-v1',
             'quantity_scale_source':f'demo-config/product/{o["p"]["id"]}/typical={o["p"]["typical"]}',
             'audit':audit},status='snapshot_only',predicted_at=at+timedelta(seconds=3))
        if selected:
            self.samples.append(dict(prediction_id=pid,order=o,at=at,stage=stage,x=x,audit=audit))
        return pid

    def simulate(self):
        self.masters(); r=self.rng
        times=sorted(self.asof-timedelta(days=r.uniform(.25,540)) for _ in range(self.count))
        for n,created in enumerate(times,1):
            p=r.choice(self.products); qty=max(1,round(r.lognormvariate(math.log(p['typical']),.55)))
            deadline=(created+timedelta(days=max(6,round(3+1.4*sum(s['median'] for s in self.suppliers)/6*p['factor']+r.gauss(7,6))))).date()
            d=r.choice(self.depts); candidates=r.sample(self.suppliers,3)
            o=dict(n=n,created=created,p=p,qty=qty,deadline=deadline,dept=d)
            options=[]
            for s in candidates:
                x,audit=self.features(s,p,qty,deadline,created,'PR_CREATED')
                offer=self.offers[s['id'],p['id']]
                estimated=3+offer['lead']*1.4*(1+.2*max(qty/p['typical']-1,0))
                cost=float(offer['price'])/(25000*(self.products.index(p)+1))
                loss=.7*cost+.9*max(estimated-(deadline-created.date()).days,0)/8
                options.append((s,x,audit,loss))
            choice=r.choices(options,weights=[math.exp(-v[3]/.45) for v in options])[0]
            s=choice[0]; o['s']=s
            wait=1+r.gammavariate(2,1); issue=created+timedelta(days=wait); o['issue']=issue
            load=choice[1]['other_open_order_count']
            median=s['median']*p['factor']*(1+.35*max(qty/p['typical']-1,0))*(1+.07*load)
            planned=max(2,round(r.lognormvariate(math.log(median),s['sigma'])))
            disruption=r.random()<s['shock_p']; extra=max(1,round(r.gammavariate(2,2))) if disruption else 0
            arrival=workday_after(issue,planned+extra); final_known=arrival+timedelta(hours=6,days=r.choices([0,1,2],[.8,.15,.05])[0])
            receipts=[]
            if qty>1 and r.random()<.55:
                first=workday_after(issue,max(1,math.floor((planned+extra)*.55)))
                first_qty=max(1,min(qty-1,round(qty*r.betavariate(3,3))))
                receipts.append(dict(qty=first_qty,arrival=first,known=first+timedelta(hours=6,days=r.choice([0,0,1]))))
            receipts.append(dict(qty=qty-sum(v['qty'] for v in receipts),arrival=arrival,known=final_known))
            final_known=max(v['known'] for v in receipts); o.update(arrival=arrival,final_known=final_known,receipts=receipts)
            confirmations=[]
            if r.random()<.92:
                confirm_at=issue+timedelta(days=r.gammavariate(2,.8))
                if confirm_at<arrival:
                    promise=workday_after(issue,max(1,planned+round(r.gauss(0,2)))).date()
                    confirmations.append(dict(known=confirm_at,promise=promise))
                    if r.random()<.35:
                        revision_at=confirm_at+timedelta(days=r.uniform(2,5))
                        if revision_at<arrival:
                            confirmations.append(dict(known=revision_at,promise=workday_after(issue,max(1,planned+extra+round(r.gauss(0,1)))).date()))
            o['confirmations']=confirmations
            requester=r.choice(self.employee[d]); approved_at=issue-timedelta(hours=1)
            approved=approved_at<=self.asof; issued=issue<=self.asof
            o['request']=self.add('purchase_requests',request_code=f'DEMO-PR-{n:05}',department_id=d,requested_by=requester,
                 source='web',status='ordered' if issued else ('approved' if approved else 'pending_approval'),input_revision=1,
                 submitted_at=created,notes='SYNTHETIC DEMO; individual employee request',created_at=created,
                 updated_at=issue if issued else created+timedelta(seconds=8))
            price=self.offers[s['id'],p['id']]['price']
            o['request_item']=self.add('purchase_request_items',request_id=o['request'],line_number=1,product_id=p['id'],
                 preferred_supplier_id=None,quantity=qty,requested_delivery_date=deadline,unit_price_snapshot=price,
                 currency='VND',line_total=price*qty,notes='DEMO frozen original deadline')
            o['po_item']=self.uid(f'po-item/{n}')
            task=self.add('analysis_tasks',request_id=o['request'],po_item_id=None,task_type='initial_analysis',input_revision=1,
                 feature_asof=created,input_snapshot={'demo':True,'request_id':o['request']},idempotency_key=f'demo-task/A/{n}',
                 status='succeeded',started_at=created,completed_at=created+timedelta(seconds=4),created_at=created)
            pred_ids={}
            for cs,x,audit,loss in options:
                pred_ids[cs['id']]=self.prediction(o,cs,task,created,'PR_CREATED',x,audit,selected=cs is s)
            report=self.add('risk_analysis_reports',task_id=task,request_id=o['request'],primary_prediction_id=pred_ids[s['id']],
                 risk_level=None,summary='DEMO heuristic selection. TabICLv2 has NOT been executed.',
                 report_data={'demo':True,'policy':'stochastic price/quoted-lead heuristic','model_executed':False},created_at=created+timedelta(seconds=5))
            ranked=sorted(options,key=lambda v:v[3])
            for rank,(cs,x,audit,loss) in enumerate(ranked,1):
                self.add('analysis_supplier_candidates',report_id=report,task_id=task,request_id=o['request'],request_item_id=o['request_item'],
                  supplier_id=cs['id'],prediction_id=pred_ids[cs['id']],unit_price_snapshot=self.offers[cs['id'],p['id']]['price'],
                  currency='VND',rank=rank,is_eligible=True,reason='DEMO available catalog offer; no real AI score',evidence_refs=[])
            proposal=self.add('proposals',proposal_code=f'DEMO-PROP-{n:05}',request_id=o['request'],version_no=1,input_revision=1,
                 is_current=True,analysis_report_id=report,generation_task_id=task,selection_policy_version='DEMO-heuristic-v1',
                 reason='DEMO automatic proposal by AI_SERVICE identity; inference not run',status='approved' if approved else 'pending',
                 created_by=self.ai,submitted_at=created+timedelta(seconds=8),created_at=created+timedelta(seconds=8))
            proposal_item=self.add('proposal_items',proposal_id=proposal,request_id=o['request'],request_item_id=o['request_item'],
                 selected_supplier_id=s['id'],prediction_id=pred_ids[s['id']],quantity=qty,unit_price_snapshot=price,
                 currency='VND',proposed_delivery_date=deadline,reason='DEMO stochastic heuristic')
            if approved:
                self.add('approval_history',proposal_id=proposal,approver_id=self.approver[d],decision='approved',reason='DEMO human approval',decided_at=approved_at)
            if issued:
                self.populate_po(o,proposal,proposal_item,price)
            self.orders.append(o)
        # Build B only after the whole timeline exists; every lookup still filters by knowledge time.
        for o in self.orders:
            if o['issue']>self.asof: continue
            at=o['issue']+timedelta(days=self.rng.choice([2,5,9,12,18]))
            if at>self.asof or self.completed(o,at): continue
            x,audit=self.features(o['s'],o['p'],o['qty'],o['deadline'],at,'PO_MONITORING',o)
            task=self.add('analysis_tasks',request_id=o['request'],po_item_id=o['po_item'],task_type='po_monitoring',input_revision=1,
                 feature_asof=at,input_snapshot={'demo':True,'po_item_id':o['po_item']},idempotency_key=f'demo-task/B/{o["n"]}',
                 status='succeeded',started_at=at,completed_at=at+timedelta(seconds=4),created_at=at)
            self.prediction(o,o['s'],task,at,'PO_MONITORING',x,audit,selected=True)
        assert all(self.rows[t] for t in TABLES),'Every application table should have demo rows'
        return self

    def populate_po(self,o,proposal,proposal_item,price):
        r=self.rng; at=self.asof; qty=o['qty']; s=o['s']; p=o['p']; issue=o['issue']; n=o['n']
        visible=self.visible_receipts(o,at); received=sum(v['qty'] for v in visible)
        conf=[c for c in o['confirmations'] if c['known']<=at]
        complete=received>=qty
        status='delivered' if complete else ('partially_received' if received else ('confirmed' if conf else 'waiting_confirmation'))
        latest=max([issue]+[v['known'] for v in visible]+[c['known'] for c in conf])
        po=self.add('purchase_orders',po_number=f'DEMO-PO-{n:05}',request_id=o['request'],proposal_id=proposal,supplier_id=s['id'],
           order_date=issue,status=status,currency='VND',total_amount=price*qty,created_by=self.po_service,created_at=issue,updated_at=latest)
        o['po']=po
        self.add('purchase_order_items',po_item_id=o['po_item'],purchase_order_id=po,proposal_item_id=proposal_item,proposal_id=proposal,
           request_id=o['request'],request_item_id=o['request_item'],line_number=1,product_id=p['id'],product_category_snapshot=p['category'],
           ordered_quantity=qty,unit='unit',unit_price=price,line_total=price*qty,
           item_status='completed' if complete else ('partially_received' if received else ('confirmed' if conf else 'open')))
        schedule=self.add('purchase_order_schedules',po_item_id=o['po_item'],schedule_number=1,scheduled_quantity=qty,
           requested_delivery_date=o['deadline'],promised_delivery_date=conf[-1]['promise'] if conf else None,
           status='completed' if complete else ('partially_received' if received else ('confirmed' if conf else 'open')),created_at=issue)
        for v in visible:
            self.add('goods_receipts',schedule_id=schedule,received_quantity=v['qty'],actual_delivery_date=v['arrival'].date(),
                received_at=v['known'],recorded_by=self.warehouse[o['dept']],notes='DEMO accepted quantity; append-only event')
        token=self.add('confirmation_tokens',purchase_order_id=po,token_hash=hashlib.sha256(f'DEMO-NONSECRET-{self.seed}-{n}'.encode()).hexdigest(),
           expires_at=issue+timedelta(days=30),issued_at=issue,consumed_at=conf[0]['known'] if conf else None,
           revoked_at=None if conf else min(at,issue+timedelta(minutes=1)))
        if conf:
            confirmation=self.add('supplier_confirmations',purchase_order_id=po,token_id=token,decision='confirmed',
                 reason='DEMO simulated supplier response',responded_at=conf[0]['known'])
            for rev,c in enumerate(conf,1):
                self.add('supplier_confirmation_items',confirmation_id=confirmation,schedule_id=schedule,revision_no=rev,
                  confirmed_quantity=qty,promised_delivery_date=c['promise'],recorded_at=c['known'],notes='DEMO promise revision')
        self.add('email_logs',purchase_order_id=po,supplier_id=s['id'],recipient_email=f'demo-{n}@example.invalid',email_type='purchase_order',
           template_code='DEMO-NO-SEND',subject=f'DEMO PO {n}',idempotency_key=f'demo-email/{n}',payload_snapshot={'demo':True,'send_disabled':True},
           status='sent',attempt_count=1,last_attempt_at=issue,provider_message_id=f'DEMO-NOT-ACTUALLY-SENT-{n}',sent_at=issue,created_at=issue)
        self.add('outbox_events',aggregate_type='purchase_order',aggregate_id=po,event_type='DEMO.po.issued',
           payload={'demo':True,'do_not_publish':True},idempotency_key=f'demo-outbox/{n}',status='published',attempt_count=1,
           available_at=issue,published_at=issue,created_at=issue)
        self.add('notifications',recipient_user_id=self.employee[o['dept']][0],type='demo_po_issued',entity_type='purchase_order',
           entity_id=po,title=f'DEMO PO {n} issued',message='Synthetic notification',created_at=issue)

    def seed_statements(self):
        yield 'SET CONSTRAINTS ALL DEFERRED;'
        for table in SEED_ORDER:
            rows=self.rows[table]
            columns=[c for c in COLUMNS[table] if any(c in row for row in rows)]
            prefix='INSERT INTO public."'+table+'" ('+','.join('"'+c+'"' for c in columns)+') VALUES\n'
            for offset in range(0,len(rows),100):
                yield prefix+',\n'.join('('+','.join(literal(row.get(c)) for c in columns)+')' for row in rows[offset:offset+100])+';'
        yield 'SET CONSTRAINTS ALL IMMEDIATE;'

    def exports(self,directory):
        directory.mkdir(parents=True,exist_ok=True)
        cutoff=sorted(o['created'] for o in self.orders)[int(.8*len(self.orders))]
        headers=['prediction_id','group_id','request_created_at','feature_asof','label_available_at','split']+FEATURES+['y']
        dataset=[]; queries=[]
        for sample in self.samples:
            o=sample['order']; known=o['final_known'] if self.completed(o,self.asof) else None
            label=int(o['arrival'].date()>o['deadline']) if known else None
            split='unlabeled'
            if known:
                split='train' if o['created']<cutoff and sample['at']<cutoff and known<=cutoff else (
                    'test' if o['created']>=cutoff else 'excluded_boundary')
            row=dict(prediction_id=sample['prediction_id'],group_id=o['po_item'],request_created_at=o['created'],
                     feature_asof=sample['at'],label_available_at=known,split=split,**sample['x'],y=label)
            (dataset if known else queries).append(row)
        def write_csv(name,rows,keys):
            with (directory/name).open('w',newline='',encoding='utf-8-sig') as f:
                w=csv.DictWriter(f,fieldnames=keys); w.writeheader()
                for row in rows:w.writerow({k:stamp(v) for k,v in row.items()})
        write_csv('model_context.csv',dataset,headers); write_csv('model_queries.csv',queries,headers)
        train=[v for v in dataset if v['split']=='train']; test=[v for v in dataset if v['split']=='test']
        write_csv('train.csv',train,headers); write_csv('test.csv',test,headers)
        assert not {v['group_id'] for v in train}&{v['group_id'] for v in test}
        assert all(v['label_available_at']<=cutoff and v['feature_asof']<cutoff for v in train)
        pairs=[]
        for o in self.orders:
            ss=[s for s in self.samples if s['order'] is o]
            a=next((s for s in ss if s['stage']=='PR_CREATED'),None)
            b=next((s for s in ss if s['stage']=='PO_MONITORING'),None)
            if a and b:
                assert a['x']['order_size_ratio']==b['x']['order_size_ratio']
                for key in FEATURES:pairs.append(dict(group_id=o['po_item'],feature=key,A=a['x'][key],B=b['x'][key],A_at=a['at'],B_at=b['at']))
                if len(pairs)>=19*10:break
        write_csv('A_B_examples.csv',pairs,['group_id','feature','A','B','A_at','B_at'])
        completed=[o for o in self.orders if self.completed(o,self.asof)]
        late=sum(o['arrival'].date()>o['deadline'] for o in completed)
        report=dict(generator='causal-v1',seed=self.seed,as_of=self.asof,orders_requested=self.count,
          row_counts={t:len(v) for t,v in self.rows.items()},completed_po_items=len(completed),late_po_items=late,
          on_time_po_items=len(completed)-late,late_rate=late/len(completed) if completed else None,
          context_rows=len(dataset),query_rows=len(queries),train_rows=len(train),test_rows=len(test),
          excluded_boundary_rows=sum(v['split']=='excluded_boundary' for v in dataset),split_cutoff=cutoff,
          overdue_B_snapshots=sum(s['stage']=='PO_MONITORING' and s['x']['days_to_deadline']<0 for s in self.samples),
          model_has_run=False,leakage_audit='passed knowledge-time checks and grouped chronological split',
          warning='Synthetic distributions are assumptions, not estimates from real suppliers; accuracy on these data does not establish real-world performance.')
        for label,predicate in [('small',lambda o:o['qty']/o['p']['typical']<=1),('large',lambda o:o['qty']/o['p']['typical']>1.5)]:
            group=[o for o in completed if predicate(o)]
            report[label]=dict(n=len(group),late_rate=sum(o['arrival'].date()>o['deadline'] for o in group)/len(group) if group else None)
        (directory/'simulation_report.json').write_text(json.dumps(report,default=stamp,ensure_ascii=False,indent=2),encoding='utf8')
        return report

def parser():
    p=argparse.ArgumentParser(description='Fresh Supplier Assistant schema + causal synthetic demo. Does not delete existing objects.')
    p.add_argument('--orders',type=int,default=1000,help='Number of personal PRs (default 1000)')
    p.add_argument('--seed',type=int,default=20261015)
    p.add_argument('--as-of',default='2026-10-15',help='Snapshot date YYYY-MM-DD, at 18:00 Asia/Ho_Chi_Minh')
    p.add_argument('--out',type=Path,default=Path(__file__).resolve().parent/'demo_output')
    p.add_argument('--export-sql',type=Path,help='Offline only: export transaction SQL and sample CSVs; no connection')
    p.add_argument('--schema-only',action='store_true',help='Create tables and helpers without demo rows')
    return p

def main():
    args=parser().parse_args()
    if not 50<=args.orders<=20000: raise SystemExit('--orders must be between 50 and 20000')
    try: asof=datetime.combine(date.fromisoformat(args.as_of),time(18),TZ)
    except ValueError: raise SystemExit('--as-of must be a valid YYYY-MM-DD date')
    demo=None if args.schema_only else Demo(args.orders,args.seed,asof).simulate()
    if args.export_sql:
        args.export_sql.parent.mkdir(parents=True,exist_ok=True)
        with args.export_sql.open('x',encoding='utf8',newline='\n') as f:
            f.write('BEGIN;\n'+SCHEMA_SQL+'\n'+HELPER_SQL+'\n')
            if demo:
                for statement in demo.seed_statements():f.write(statement+'\n')
            f.write('\nCOMMIT;\n')
        if demo:demo.exports(args.out)
        print('Exported offline:',args.export_sql.resolve()); return
    try: import psycopg
    except ImportError: raise SystemExit('Install first: python -m pip install "psycopg[binary]"')
    dsn=os.environ.get('SUPABASE_DB_URL') or getpass.getpass('Paste PostgreSQL connection URI (hidden; not stored): ')
    if not dsn.strip(): raise SystemExit('Missing database connection URI')
    print('Connecting. No emails, API calls, or model inference will be performed.')
    try:
        options=psycopg.conninfo.conninfo_to_dict(dsn)
        options.setdefault('connect_timeout','20'); options.setdefault('sslmode','require')
        with psycopg.connect(**options) as conn:
            with conn.cursor() as cur:
                cur.execute("SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname=ANY(%s)",(TABLES,))
                collisions=[v[0] for v in cur.fetchall()]
                if collisions: raise RuntimeError('Existing application objects: '+', '.join(collisions)+'. Use a fresh target; this script never drops data.')
                cur.execute("SELECT proname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname=ANY(%s)",(['sa_has_role','sa_po_progress','sa_training_rows'],))
                if cur.fetchall():raise RuntimeError('Helper functions already exist. Use a fresh target; functions are not overwritten.')
                cur.execute("SELECT rolname FROM pg_roles WHERE rolname IN ('anon','authenticated')")
                if len(cur.fetchall())!=2: raise RuntimeError('This installer expects a Supabase PostgreSQL database (anon/authenticated roles).')
                cur.execute(SCHEMA_SQL); cur.execute(HELPER_SQL)
                if demo:
                    for statement in demo.seed_statements():cur.execute(statement)
                cur.execute(VERIFY_SQL)
                actual=dict(zip([d.name for d in cur.description],cur.fetchone()))
                expected=dict(tables=27,columns=293,primary_keys=27,foreign_keys=56,checks=83,
                              ordinary_uniques=40,partial_uniques=3,rls_tables=27,client_table_grants=0,policies=0,user_triggers=0)
                for key,value in expected.items():
                    if actual[key]!=value:raise RuntimeError(f'Verification failed: {key}={actual[key]}, expected {value}')
                if demo:
                    for table in TABLES:
                        cur.execute('SELECT count(*) FROM public."'+table+'"')
                        if cur.fetchone()[0]!=len(demo.rows[table]):raise RuntimeError('Row-count mismatch: '+table)
                    cur.execute('SELECT count(*) FROM public.sa_training_rows(%s)',(asof,))
                    known_count=cur.fetchone()[0]
                    expected_labels=sum(demo.completed(s['order'],asof) for s in demo.samples)
                    if known_count!=expected_labels:raise RuntimeError('Training-row helper mismatch')
            conn.commit()
    except Exception as exc:
        # Do not echo a connection URI/password into logs.
        if isinstance(exc,RuntimeError): print(str(exc),file=sys.stderr)
        else:
            detail=getattr(getattr(exc,'diag',None),'message_primary',None)
            print(f'Database operation failed ({type(exc).__name__}). Changes in this transaction were rolled back. '+
                  (detail or 'Check connection settings and permissions.'),file=sys.stderr)
        raise SystemExit(1)
    try:
        args.out.mkdir(parents=True,exist_ok=True)
        report=demo.exports(args.out) if demo else {}
        (args.out/'database_verification.json').write_text(json.dumps(actual,default=stamp,indent=2),encoding='utf8')
        print('Created and verified: 27 tables + 3 SQL helper functions.')
        if demo:print(f'Demo PRs: {args.orders}; labeled context rows: {report["context_rows"]}; CSV/report: {args.out.resolve()}')
    except OSError:
        print('Database committed successfully; local CSV export failed. Use sa_training_rows() or re-export offline to a writable directory.',file=sys.stderr)

if __name__=='__main__': main()
